"""Reference-led shortlist, retaining the existing opportunity API and actions."""

OPPORTUNITIES_BODY = r"""<main class="wrap opportunities-workspace"><a class="back-overview" href="/">Back to overview</a><h1>Opportunities</h1><p>Curated, analyzed, and ranked for your career objectives.</p><p class="queue-summary">__OPPORTUNITIES__ opportunities · __SHORTLISTED__ shortlisted · __JOBS__ jobs discovered</p><form class="filters" id="filters"><label class="opportunity-search"><img src="/brand/icons/search.svg" width="16" height="16" alt=""><input name="query" id="opportunity-query" type="search" aria-label="Search opportunities" placeholder="Search opportunities…"></label><div class="filter-chips" aria-label="Quick filters"><button type="button" data-filter="all" aria-pressed="true">All</button><button type="button" data-filter="confidence" aria-pressed="false">High confidence</button><button type="button" data-filter="remote" aria-pressed="false">Remote</button><button type="button" id="more-filters" aria-expanded="false" aria-controls="advanced-filters">More filters</button></div><div id="advanced-filters" hidden><input name="location" placeholder="Location" aria-label="Location"><input name="min_salary" type="number" placeholder="Min salary" aria-label="Minimum salary"><input name="max_salary" type="number" placeholder="Max salary" aria-label="Maximum salary"><input name="industry" placeholder="Industry" aria-label="Industry"><button type="submit">Filter jobs</button><button type="button" id="clear">Clear</button></div></form><section class="queue" id="queue"><h2>Shortlist</h2><div class="row"><div><strong>Loading shortlisted opportunities...</strong></div></div></section><p id="error" role="alert"></p><p id="status" role="status"></p><p class="save-note">Saved opportunities stay in this browser for your current profile.</p><script>__ASK__function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}let all=[];let quickFilter='all';function showError(message){document.querySelector('#status').textContent='';document.querySelector('#error').textContent=message||'The request failed.';}function showStatus(message){document.querySelector('#error').textContent='';document.querySelector('#status').textContent=message||'';}async function prepare(id){const r=await fetch(`/api/opportunities/${encodeURIComponent(id)}/prepare`,{method:'POST'});const text=await r.text();let d={};try{d=JSON.parse(text)}catch(e){d={detail:text}}if(!r.ok){const detail=typeof d.detail==='string'?d.detail:(text||'Preparation failed');showError(detail);return}showStatus(`Package ${d.status}. Unresolved questions: ${(d.unresolved_questions||[]).length}`)}async function pass(id){if(!await ask('Pass on this role? It leaves your list and will not come back.',{confirmLabel:'Pass'}))return;const r=await fetch(`/api/opportunities/${encodeURIComponent(id)}/pass`,{method:'POST'});const text=await r.text();let d={};try{d=JSON.parse(text)}catch(e){d={detail:text}}if(!r.ok){showError(typeof d.detail==='string'?d.detail:(text||'Pass failed'));return}showStatus('Passed. This role will not come back.');all=all.filter(o=>o.id!==id);applyFilters()}function render(rows){const q=document.querySelector('#queue');q.innerHTML='<h2>Shortlist</h2>'+ (rows.length?rows.map(o=>`<div class="row ranked-opportunity"><span class="opportunity-initials" aria-hidden="true">${esc(String(o.company||'?').split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]).join(''))}</span><div class="ranked-copy"><span class="ranked-company">${esc(o.company)}</span><strong><span class="rank-number">${o.rank_position==null?'':esc(o.rank_position)+'.'}</span> <a href="/opportunities/${encodeURIComponent(o.id)}">${esc(o.title)}</a></strong><span class="ranked-meta">${esc(o.location||'Location not listed')} · ${esc(o.status)}</span><details class="opportunity-evidence"><summary>Match evidence</summary><p>${esc(o.why_this_job||o.shortlist_reason||'Shortlisted by the ranking engine.')}</p><p>Biggest gap: ${esc(o.primary_gap||'none noted')}</p></details></div><div class="ranked-pay"><strong>${esc(o.compensation_text||'Pay: not listed')}</strong><span class="match-label">${o.fit_score==null?'Fit pending':`Fit ${Math.round(o.fit_score*100)}%`}</span><span class="confidence-label">Confidence: ${o.confidence==null?'not assessed':esc(Math.round(o.confidence*100)+'%')}</span></div><div class="ranked-actions"><button type="button" data-id="${esc(o.id)}">Prepare application</button><button type="button" class="pass secondary" data-pass="${esc(o.id)}">Pass</button></div>${artemisSaveButton(o.id,o.company)}</div>`).join(''):'<div class="row"><div><strong>No jobs match those filters.</strong></div></div>');artemisSyncSaves();q.querySelectorAll('button[data-id]').forEach(btn=>btn.addEventListener('click',()=>prepare(btn.dataset.id)));q.querySelectorAll('button[data-pass]').forEach(btn=>btn.addEventListener('click',()=>pass(btn.dataset.pass)));}fetch('/api/opportunities').then(async r=>{if(!r.ok)throw new Error(await r.text());return r.json()}).then(d=>{all=Array.isArray(d.opportunities)?d.opportunities:[];applyFilters()}).catch(error=>{document.querySelector('#queue').innerHTML='<h2>Shortlist</h2><div class="row"><div><strong>The opportunity queue could not be loaded.</strong></div></div>';showError(error.message)});function applyFilters(){const f=new FormData(document.querySelector('#filters')),query=String(f.get('query')||'').trim().toLowerCase(),loc=String(f.get('location')||'').trim().toLowerCase(),ind=String(f.get('industry')||'').trim().toLowerCase(),min=Number(f.get('min_salary'))||0,max=Number(f.get('max_salary'))||Infinity;render(all.filter(o=>(!query||`${o.company} ${o.title} ${o.location||''}`.toLowerCase().includes(query))&&(!loc||String(o.location||'').toLowerCase().includes(loc))&&(!ind||`${o.company} ${o.title} ${o.industry??''}`.toLowerCase().includes(ind))&&(!min||(o.salary_max!=null&&o.salary_max>=min))&&(!isFinite(max)||(o.salary_min!=null&&o.salary_min<=max))&&(quickFilter!=='confidence'||(o.confidence!=null&&o.confidence>=.75))&&(quickFilter!=='remote'||o.remote_status==='REMOTE'||((!o.remote_status||o.remote_status==='UNKNOWN')&&/remote/i.test(o.location||'')))))}
document.querySelector('#filters').addEventListener('submit',e=>{e.preventDefault();applyFilters()});
document.querySelector('#opportunity-query').addEventListener('input',applyFilters);
document.querySelector('#filters').querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{quickFilter=button.dataset.filter;document.querySelector('#filters').querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));applyFilters()}));
document.querySelector('#more-filters').onclick=()=>{const panel=document.querySelector('#advanced-filters');panel.hidden=!panel.hidden;document.querySelector('#more-filters').setAttribute('aria-expanded',String(!panel.hidden))};
document.querySelector('#clear').onclick=()=>{document.querySelector('#filters').reset();quickFilter='all';document.querySelector('#filters').querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter==='all')));render(all)};</script></main>"""
